def time_str_to_utc_timestamp(time_str, time_format="%Y-%m-%d %H:%M:%S"):
    time_str = parser.parse(time_str, tzinfos=TIME_ZONE_CITY_MAPPING)
    time_str = time_str.astimezone(pytz.timezone("UTC")).strftime(time_format)
    timestamp = calendar.timegm(time.strptime(time_str, time_format))
    return timestamp


def get_current_utc_timestamp():
    timestamp = calendar.timegm(datetime.now(tz=pytz.timezone("UTC")).timetuple())
    return timestamp


def get_duration(start_utc_time, end_utc_time):
    duration = (end_utc_time - start_utc_time) / 60
    duration = math.ceil(duration)
    return duration
